import backtrader as bt
import math


class NXXTMultiMovingAverageTrendFollowingStrategy(bt.Strategy):
    params = (
        ('sma_short_period', 30),
        ('sma_medium_period', 60),
        ('sma_long_period', 120),
        ('consolidation_period', 5),
        ('consolidation_range', 0.05),
        ('take_profit', 0.10),
        ('risk_per_trade', 0.02),
        ('atr_period', 14),
        ('atr_average_period', 30),
        ('high_volatility_multiple', 1.50),
    )

    def __init__(self):
        self.sma30 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_short_period
        )
        self.sma60 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_medium_period
        )
        self.sma120 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_long_period
        )
        self.atr14 = bt.indicators.AverageTrueRange(
            self.data, period=self.p.atr_period
        )
        self.atr30_average = bt.indicators.SimpleMovingAverage(
            self.atr14, period=self.p.atr_average_period
        )
        self.consolidation_high = bt.indicators.Highest(
            self.data.close, period=self.p.consolidation_period
        )
        self.consolidation_low = bt.indicators.Lowest(
            self.data.close, period=self.p.consolidation_period
        )
        self.order = None
        self.entry_price = None

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.isbuy():
                self.entry_price = order.executed.price
            elif not self.position:
                self.entry_price = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            self.order = None

    def next(self):
        if self.order:
            return

        if self.position:
            if self.data.high[0] >= self.entry_price * (1.0 + self.p.take_profit):
                self.order = self.close()
            elif self.data.close[0] < self.sma30[0]:
                self.order = self.close()
            return

        moving_averages_support_price = (
            self.data.close[0] > self.sma30[0]
            and self.data.close[0] > self.sma60[0]
            and self.data.close[0] > self.sma120[0]
        )
        moving_averages_rising = (
            self.sma30[0] > self.sma30[-1]
            and self.sma60[0] > self.sma60[-1]
            and self.sma120[0] > self.sma120[-1]
        )
        prior_range_is_consolidated = (
            (self.consolidation_high[-1] - self.consolidation_low[-1])
            / self.consolidation_low[-1]
            <= self.p.consolidation_range
        )
        breaks_above_consolidation = (
            self.data.close[0] > self.consolidation_high[-1]
        )
        volatility_is_not_high = (
            self.atr14[0]
            <= self.p.high_volatility_multiple * self.atr30_average[0]
        )

        if (
            moving_averages_support_price
            and moving_averages_rising
            and prior_range_is_consolidated
            and breaks_above_consolidation
            and volatility_is_not_high
        ):
            signal_entry_price = self.data.close[0]
            stop_price = self.sma30[0]
            risk_per_share = signal_entry_price - stop_price
            maximum_trade_risk = self.broker.getvalue() * self.p.risk_per_trade
            size = math.floor(maximum_trade_risk / risk_per_share)
            if size > 0:
                self.order = self.buy(size=size)
